using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private readonly ITransformer _model;
    private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
    private readonly IReadOnlyList<string> _categoryLabels;
    private readonly EvaluationResponse _evaluationMetrics;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 0);

        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        _model = pipeline.Fit(dataView);
        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);

        // Extract ordered category labels from the key mapping
        var transformedData = _model.Transform(dataView);
        var labelColumn = transformedData.Schema["Label"];
        var keyType = labelColumn.Type as Microsoft.ML.Data.KeyDataViewType;
        VBuffer<ReadOnlyMemory<char>> labelValues = default;
        transformedData.Schema["Label"].GetKeyValues(ref labelValues);
        _categoryLabels = labelValues.DenseValues().Select(v => v.ToString()).ToList();

        // Evaluate on training data (small dataset — cross-validation would be ideal with more data)
        _evaluationMetrics = Evaluate(dataView);
    }

    private EvaluationResponse Evaluate(IDataView data)
    {
        var predictions = _model.Transform(data);
        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");

        var response = new EvaluationResponse
        {
            MacroAccuracy = metrics.MacroAccuracy,
            MicroAccuracy = metrics.MicroAccuracy,
            LogLoss = metrics.LogLoss,
            LogLossReduction = metrics.LogLossReduction,
        };

        for (int i = 0; i < metrics.PerClassLogLoss.Count && i < _categoryLabels.Count; i++)
        {
            response.PerCategoryMetrics.Add(new CategoryMetric
            {
                Category = _categoryLabels[i],
                Precision = i < metrics.PerClassLogLoss.Count ? 1.0 - metrics.PerClassLogLoss[i] : 0,
                Recall = metrics.MacroAccuracy
            });
        }

        // Re-evaluate with confusion matrix for precise per-class precision/recall
        var confusionMatrix = metrics.ConfusionMatrix;
        var precisions = confusionMatrix.PerClassPrecision;
        var recalls = confusionMatrix.PerClassRecall;

        response.PerCategoryMetrics.Clear();
        for (int i = 0; i < _categoryLabels.Count; i++)
        {
            response.PerCategoryMetrics.Add(new CategoryMetric
            {
                Category = _categoryLabels[i],
                Precision = i < precisions.Count ? precisions[i] : 0,
                Recall = i < recalls.Count ? recalls[i] : 0
            });
        }

        return response;
    }

    public PredictionResponse Predict(TicketRequest request)
    {
        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var confidence = new Dictionary<string, float>();
        for (int i = 0; i < _categoryLabels.Count && i < prediction.Score.Length; i++)
        {
            confidence[_categoryLabels[i]] = prediction.Score[i];
        }

        return new PredictionResponse
        {
            PredictedCategory = prediction.Category,
            Confidence = confidence
        };
    }

    public EvaluationResponse GetMetrics() => _evaluationMetrics;
}

