1. using Microsoft.ML;
2. using Microsoft.ML.Data;
3. using TicketClassifier.Models;
4. 
5. namespace TicketClassifier.Services;
6. 
7. public class TicketClassifierService
8. {
9.     private readonly MLContext _mlContext;
10.     private readonly ITransformer _model;
11.     private readonly PredictionEngine<TicketData, TicketPrediction> _predictionEngine;
12.     private readonly IReadOnlyList<string> _categoryLabels;
13.     private readonly EvaluationResponse _evaluationMetrics;
14. 
15.     public TicketClassifierService(string dataPath)
16.     {
17.         _mlContext = new MLContext(seed: 0);
18. 
19.         var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
20.             dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
21. 
22.         var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category))
23.             .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeatures", nameof(TicketData.Subject)))
24.             .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeatures", nameof(TicketData.Description)))
25.             .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeatures", "DescriptionFeatures", nameof(TicketData.Priority)))
26.             .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
27.             .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
28. 
29.         _model = pipeline.Fit(dataView);
30.         _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketData, TicketPrediction>(_model);
31. 
32.         // Extract ordered category labels from the key mapping
33.         var transformedData = _model.Transform(dataView);
34.         var labelColumn = transformedData.Schema["Label"];
35.         VBuffer<ReadOnlyMemory<char>> labelValues = default;
36.         labelColumn.GetKeyValues(ref labelValues);
37.         _categoryLabels = labelValues.DenseValues().Select(v => v.ToString()).ToList();
38. 
39.         // Evaluate on training data (small dataset — cross-validation would be ideal with more data)
40.         _evaluationMetrics = Evaluate(dataView);
41.     }
42. 
43.     private EvaluationResponse Evaluate(IDataView data)
44.     {
45.         var predictions = _model.Transform(data);
46.         var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");
47. 
48.         var response = new EvaluationResponse
49.         {
50.             MacroAccuracy = metrics.MacroAccuracy,
51.             MicroAccuracy = metrics.MicroAccuracy,
52.             LogLoss = metrics.LogLoss,
53.             LogLossReduction = metrics.LogLossReduction,
54.         };
55. 
56.         for (int i = 0; i < metrics.PerClassLogLoss.Count && i < _categoryLabels.Count; i++)
57.         {
58.             response.PerCategoryMetrics.Add(new CategoryMetric
59.             {
60.                 Category = _categoryLabels[i],
61.                 Precision = i < metrics.PerClassLogLoss.Count ? 1.0 - metrics.PerClassLogLoss[i] : 0,
62.                 Recall = metrics.MacroAccuracy
63.             });
64.         }
65. 
66.         // Re-evaluate with confusion matrix for precise per-class precision/recall
67.         var confusionMatrix = metrics.ConfusionMatrix;
68.         var precisions = confusionMatrix.PerClassPrecision;
69.         var recalls = confusionMatrix.PerClassRecall;
70. 
71.         response.PerCategoryMetrics.Clear();
72.         for (int i = 0; i < _categoryLabels.Count; i++)
73.         {
74.             response.PerCategoryMetrics.Add(new CategoryMetric
75.             {
76.                 Category = _categoryLabels[i],
77.                 Precision = i < precisions.Count ? precisions[i] : 0,
78.                 Recall = i < recalls.Count ? recalls[i] : 0
79.             });
80.         }
81. 
82.         return response;
83.     }
84. 
85.     public PredictionResponse Predict(TicketRequest request)
86.     {
87.         var ticketData = new TicketData
88.         {
89.             Subject = request.Subject,
90.             Description = request.Description,
91.             Priority = request.Priority
92.         };
93. 
94.         var prediction = _predictionEngine.Predict(ticketData);
95. 
96.         var confidence = new Dictionary<string, float>();
97.         for (int i = 0; i < _categoryLabels.Count && i < prediction.Score.Length; i++)
98.         {
99.             confidence[_categoryLabels[i]] = prediction.Score[i];
100.         }
101. 
102.         return new PredictionResponse
103.         {
104.             PredictedCategory = prediction.Category,
105.             Confidence = confidence
106.         };
107.     }
108. 
109.     public EvaluationResponse GetMetrics() => _evaluationMetrics;
110. }
111.

