    private readonly EvaluationResponse _evaluationMetrics;

    public TicketClassifierService(string dataPath)
    {
        _mlContext = new MLContext(seed: 0);

        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Combine subject + description into a single text column, then featurize once to reduce memory
        var pipeline = _mlContext.Transforms.CustomMapping<TicketData, CombinedText>(
                (input, output) => output.Text = $"{input.Subject} {input.Description}",
                contractName: null)
            .Append(_mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketData.Category)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("TextFeatures", nameof(CombinedText.Text)))
            .Append(_mlContext.Transforms.Concatenate("Features", "TextFeatures", nameof(TicketData.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

